(function(){'use strict';const root=document.documentElement;const prefersReduced=window.matchMedia('(prefers-reduced-motion: reduce)');function readConfig(){const dataNode=document.getElementById('site-data');let data={};try{data=JSON.parse((dataNode&&dataNode.textContent)||'{}');}catch(e){data={};}
const bg=data.background||{};if(bg.opacity!==undefined)root.style.setProperty('--bg-opacity',String(bg.opacity));return data;}
function assignReveal(scope){const groups=new Map();(scope||document).querySelectorAll('[data-reveal]').forEach((node)=>{const parent=node.parentElement||document.body;const key=parent;const index=groups.get(key)||0;node.style.setProperty('--reveal-i',String(index));groups.set(key,index+1);});}
function reveal(){requestAnimationFrame(()=>requestAnimationFrame(()=>root.classList.add('ink-ready')));}
function initParallax(){const nodes=[...document.querySelectorAll('[data-parallax]')];if(!nodes.length||prefersReduced.matches)return;let ticking=false;const update=()=>{ticking=false;const scroll=window.scrollY;if(scroll>window.innerHeight*1.2)return;nodes.forEach((node)=>{const factor=parseFloat(node.getAttribute('data-parallax'))||0.1;node.style.transform='translate3d(0,'+(scroll*factor).toFixed(2)+'px,0)';});};window.addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(update);}},{passive:true});update();}
let observeCards=null;function initScrollReveal(){if(!('IntersectionObserver'in window)||prefersReduced.matches)return;const observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting)return;entry.target.style.animation='card-in .62s cubic-bezier(.22,.61,.36,1) both';observer.unobserve(entry.target);});},{rootMargin:'0px 0px -8% 0px',threshold:0.06});observeCards=(scope)=>{(scope||document).querySelectorAll('.card, .tl-year, .archive-year, .cloud__item').forEach((node)=>{if(node.dataset.revealed)return;node.dataset.revealed='1';observer.observe(node);});};observeCards(document);document.addEventListener('ink:view',()=>observeCards());window.addEventListener('hashchange',()=>setTimeout(()=>observeCards(),60));}
function initTimelineScroll(){document.querySelectorAll('.tl-year__body').forEach((body)=>{body.style.maxHeight=body.scrollHeight+'px';});}
let localTimeTimer=null;function initLocalTime(){const render=()=>{const nodes=document.querySelectorAll('[data-local-time]');if(!nodes.length)return;const offset=Number(nodes[0].getAttribute('data-offset')||8);const utc=Date.now()+new Date().getTimezoneOffset()*60000;const local=new Date(utc+offset*3600000);const hh=String(local.getHours()).padStart(2,'0');const mm=String(local.getMinutes()).padStart(2,'0');nodes.forEach((node)=>{node.textContent=hh+':'+mm+' (UTC+'+offset+')';});};render();if(!localTimeTimer)localTimeTimer=setInterval(render,30000);}
document.addEventListener('DOMContentLoaded',()=>{readConfig();assignReveal(document);reveal();initParallax();initScrollReveal();initTimelineScroll();initLocalTime();document.addEventListener('ink:view',()=>{assignReveal(document.getElementById('view-dynamic')||document);});document.addEventListener('ink:navigate',(event)=>{const main=(event.detail&&event.detail.main)||document;assignReveal(main);if(observeCards)observeCards(main);initLocalTime();});});window.addEventListener('load',()=>root.classList.add('ink-ready'));})();